<?php declare(strict_types=1);use NpmGateway\Services\RmCorrectionStatus;use NpmGateway\Support\GatewayDateTimeFormatter;$e=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$components=dirname(__DIR__,2).'/components';$labels=RmCorrectionStatus::LABELS;$badges=RmCorrectionStatus::BADGES;ob_start();$heading='RM Corrections';$description='Submit Rent Manager correction requests and follow their status.';$eyebrow='Community Actions';$actionsHtml='<a class="btn gateway-button gateway-button--primary" href="/community-actions/'.$e($context->propertySlug).'/rm-corrections/create">New RM Correction Request</a>';require$components.'/page-header.php';?><div class="gateway-review-summary d-flex flex-wrap gap-2" role="status" aria-label="RM Corrections status summary"><?php foreach($labels as$s=>$l):$statusLabel=$counts[$s].' '.$l;$statusType=$badges[$s];require$components.'/status-badge.php';endforeach;?></div><form class="gateway-filter-bar" method="get"><label>Search<input class="form-control" type="search" name="search" value="<?=$e($search)?>"></label><label>Status<select class="form-select" name="status"><option value="">All statuses</option><?php foreach($labels as$v=>$l):?><option value="<?=$v?>"<?=$status===$v?' selected':''?>><?=$l?></option><?php endforeach;?></select></label><button class="btn btn-secondary">Apply Filters</button></form><?php if(!$requests):$emptyTitle=$search!==''||$status!==''?'No RM correction requests match these filters.':'No RM correction requests have been submitted.';$emptyMessage=$search!==''||$status!==''?'':'Submit a correction request using the button above.';$emptyIconHtml=$emptyActionHtml='';require$components.'/empty-state.php';else:?><div class="table-responsive"><table class="table gateway-directory-table"><thead><tr><th>Lot / Address</th><th>Tenant</th><th>Submitted</th><th>Status</th><th>Last Updated</th><th>Action</th></tr></thead><tbody><?php foreach($requests as$r):?><tr><td><?=$e($r['l